class BeachFrontEnd : public FEMultiMenu
{
	char pad004[0x48];
	void* highlighted;
	char pad050[0xb0];
	PanelFile panel;
	char pad104[0x724];
	int goal_num[3];
	int on_challenge;
	char pad834[0x60];
	void* fe_return;
	char pad898[0x70];
	int voiceOverStage;
	nslSoundId voiceOverSound;
	char pad910[0x10];
	int in_description_mode;
	int in_bio_mode;
	char pad928[0x598];
	int bio_counter;
	char padEC4[4];
	int bio_down_pressed;
	char padECC[0x3c];
	int in_frontend;
	char padF0C[0x10];
	int ignore_controller;

	void SetOnChallenge(int);

public:
	void OnDown(int);
};

void BeachFrontEnd::OnDown(int c)
{
	if((ignore_controller || panel.IsSliding()) && !in_frontend) return;
	if(in_description_mode) return;
	if(in_bio_mode)
	{
		bio_down_pressed = true;
		bio_counter = 3;
		return;
	}
	if(!os_developer_options::inst()->is_flagged(os_developer_options::FLAG_NO_AUDIO))
		nslStopSound(voiceOverSound);
	voiceOverStage = 0;
	bool on_beach =
		highlighted != fe_return
	;
	if (!in_frontend)
		SoundScriptManager::inst()->unpause();

	if(on_beach)
	{
		if(goal_num[1] != 0 && on_challenge == 0)
		{
			SetOnChallenge(1);
			SoundScriptManager::inst()->playEvent(SoundScriptManager::SS_FE_UPDOWN);
		}
		else if(goal_num[2] != 0 && (on_challenge == 1 || (on_challenge == 0 && goal_num[1] == 0)))
		{
			SetOnChallenge(2);
			SoundScriptManager::inst()->playEvent(SoundScriptManager::SS_FE_UPDOWN);
		}
		else
			SoundScriptManager::inst()->playEvent(SoundScriptManager::SS_FE_ERROR);
	}
	else
	{
		FEMultiMenu::OnDown(c);
	}
	if (!in_frontend)
		SoundScriptManager::inst()->pause();
}
